import 'package:flutter/material.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:cloud_firestore/cloud_firestore.dart';
import 'firebase_options.dart';
Future<void> main()async{WidgetsFlutterBinding.ensureInitialized();await Firebase.initializeApp(options:DefaultFirebaseOptions.currentPlatform);runApp(const App());}
class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(title:'Malkify Tasks',theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xFF4263EB)),useMaterial3:true,scaffoldBackgroundColor:const Color(0xFFF5F7FC),appBarTheme:const AppBarTheme(backgroundColor:Color(0xFFF5F7FC),surfaceTintColor:Colors.transparent)),home:const Home());}
class Home extends StatefulWidget{const Home({super.key});@override State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{final email=TextEditingController(),password=TextEditingController(),task=TextEditingController();bool signup=false;User? get user=>FirebaseAuth.instance.currentUser;
Future<void> auth()async{try{if(signup){await FirebaseAuth.instance.createUserWithEmailAndPassword(email:email.text.trim(),password:password.text);}else{await FirebaseAuth.instance.signInWithEmailAndPassword(email:email.text.trim(),password:password.text);}}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}setState((){});}
Future<void> add()async{final t=task.text.trim();if(t.isEmpty||user==null)return;await FirebaseFirestore.instance.collection('users').doc(user!.uid).collection('tasks').add({'title':t,'done':false,'createdAt':FieldValue.serverTimestamp()});task.clear();}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Malkify Tasks'),actions:[if(user!=null)IconButton(onPressed:()async{await FirebaseAuth.instance.signOut();setState((){});},icon:const Icon(Icons.logout))]),body:user==null?Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:440),child:Card(child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.task_alt,size:48,color:Color(0xFF4263EB)),const SizedBox(height:12),Text(signup?'Create your account':'Welcome back',style:Theme.of(c).textTheme.headlineSmall),const SizedBox(height:18),TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'Email',prefixIcon:Icon(Icons.email_outlined))),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password',prefixIcon:Icon(Icons.lock_outline))),const SizedBox(height:12),SizedBox(width:double.infinity,child:FilledButton(onPressed:auth,child:Text(signup?'Create account':'Sign in'))),TextButton(onPressed:()=>setState(()=>signup=!signup),child:Text(signup?'Already registered? Sign in':'New here? Create account'))]))))):Column(children:[Padding(padding:const EdgeInsets.all(16),child:Row(children:[Expanded(child:TextField(controller:task,decoration:const InputDecoration(hintText:'Add a task'))),IconButton(onPressed:add,icon:const Icon(Icons.add_circle))])),Expanded(child:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('users').doc(user!.uid).collection('tasks').orderBy('createdAt',descending:true).snapshots(),builder:(c,s){if(s.hasError)return Center(child:Text(s.error.toString()));if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(padding:const EdgeInsets.symmetric(horizontal:12,vertical:8),children:s.data!.docs.map((d){final data=d.data();return Card(margin:const EdgeInsets.symmetric(vertical:5),child:CheckboxListTile(value:data['done']==true,title:Text(data['title']??''),onChanged:(v)=>d.reference.update({'done':v??false}),secondary:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()=>d.reference.delete()));}).toList());}))]));}
